static const TRPAIR *activePairs = 0;
static int activeCount = 0;
static char activeCode[8] = "en";

const char *MenuStringsLanguage(void)
{
	return activeCode;
}

//"ms0:/PSP/GAME/RiseofthePenguinsGB_de/roms/game_de.gb" -> "de"
//".../roms/game_pt_BR.gb" -> "pt_BR";  ".../roms/game.gb" -> nothing, so English.
static int LanguageFromRom(const char *romPath, char *dst, int size)
{
	static const char prefix[] = "game_";
	const char *base, *p;
	int n = 0, i;

	dst[0] = 0;
	if (!romPath || !romPath[0])
		return 0;

	base = strrchr(romPath, '/');
	if (!base)
		base = strrchr(romPath, '\\');
	base = base ? base + 1 : romPath;

	//The PSP hands back 8.3 directory entries in upper case ("GAME_DE.GB"), so
	//match and extract without regard to case. Testing this on a PC, where the
	//name reads back as typed, is what hid it the first time.
	for (i = 0; i < 5; i++)		{
		 char c = base[i];
		 if (c >= 'A' && c <= 'Z')
			 c += 32;
		 if (c != prefix[i])
			 return 0;
	}
	for (p = base + 5; *p && *p != '.' && n < size - 1; p++)		{
		char c = *p;
		if (c >= 'A' && c <= 'Z')
			c += 32;
		dst[n++] = c;
	}
	dst[n] = 0;
	return n > 0;
}


void MenuStringsInit(const char *romPath)
{
	char code[8];
	int i;

	if (!LanguageFromRom(romPath, code, sizeof(code)))
		//Nothing to go on: keep whatever was already chosen rather than
		//dropping back to English - this runs from every UI entry point.
		return;

	for (i = 0; languages[i].code; i++)		{
		if (!strcmp(languages[i].code, code))		{
			activePairs = languages[i].pairs;
			activeCount = languages[i].count;
			safe_strcpy(activeCode, code, sizeof(activeCode));
			return;
		}
	}
	//A build whose language has no table yet still runs, in English
}

const char *Tr(const char *en)
{
	int lo = 0, hi = activeCount - 1;

	if (!en || !activePairs)
		return en;

	while (lo <= hi)		{
		int mid = (lo + hi) / 2;
		int c = strcmp(en, activePairs[mid].en);
		if (c == 0)
			return activePairs[mid].tr;
		if (c < 0)
			hi = mid - 1;
		else
			lo = mid + 1;
	}
	//Untranslated: the English reads correctly, which beats a blank row
	return en;
}
